rgbaScalers.reloaded_ra2 = rgbaScalers.xbr;

function getScaledUnitBuffer(srcImgData, drawW, drawH, method, flip, brightness, contrast) {
    if (
        _cachedScaled.src === srcImgData &&
        _cachedScaled.method === method &&
        _cachedScaled.flip === flip &&
        _cachedScaled.drawW === drawW &&
        _cachedScaled.drawH === drawH &&
        _cachedScaled.brightness === brightness &&
        _cachedScaled.contrast === contrast &&
        _cachedScaled.data
    ) {
        return _cachedScaled.data;
    }

    const sw = srcImgData.width;
    const sh = srcImgData.height;
    const srcU32 = new Uint32Array(srcImgData.data.buffer, srcImgData.data.byteOffset, sw * sh);

    // 1. Apply flip if requested
    let baseU32 = srcU32;
    if (flip === 'h' || flip === 'v') {
        baseU32 = new Uint32Array(sw * sh);
        for (let y = 0; y < sh; y++) {
            const sy = (flip === 'v') ? (sh - 1 - y) : y;
            for (let x = 0; x < sw; x++) {
                const sx = (flip === 'h') ? (sw - 1 - x) : x;
                baseU32[y * sw + x] = srcU32[sy * sw + sx];
            }
        }
    }

    // 2. Run discrete pixel-art upscaler if selected
    let workU32 = baseU32;
    let ww = sw;
    let wh = sh;
    if (rgbaScalers[method]) {
        if (
            _cachedUpscale.src === srcImgData &&
            _cachedUpscale.method === method &&
            _cachedUpscale.flip === flip &&
            _cachedUpscale.data
        ) {
            workU32 = _cachedUpscale.data;
            ww = _cachedUpscale.w;
            wh = _cachedUpscale.h;
        } else {
            const up = rgbaScalers[method](baseU32, sw, sh);
            workU32 = up.data;
            ww = up.w;
            wh = up.h;
            _cachedUpscale = { src: srcImgData, method, flip, w: ww, h: wh, data: workU32 };
        }
    }

    // 3. Resample (ww x wh) -> (drawW x drawH) using Smart (Area Average) or Nearest
    const outBytes = new Uint8ClampedArray(drawW * drawH * 4);
    const workBytes = new Uint8Array(workU32.buffer, workU32.byteOffset, ww * wh * 4);
    const useNearest = (method === 'nearest');

    const xr = ww / drawW;
    const yr = wh / drawH;
    const cFactor = (259 * (contrast + 255)) / (255 * (259 - contrast));
    const bOffset = (brightness / 100) * 255;

    for (let y = 0; y < drawH; y++) {
        for (let x = 0; x < drawW; x++) {
            let r = 0, g = 0, b = 0, a = 0;
            if (useNearest) {
                const sx = Math.min(ww - 1, Math.floor(x * xr));
                const sy = Math.min(wh - 1, Math.floor(y * yr));
                const si = (sy * ww + sx) * 4;
                r = workBytes[si];
                g = workBytes[si + 1];
                b = workBytes[si + 2];
                a = workBytes[si + 3];
            } else {
                // Smart (Area Average)
                const sx1 = Math.floor(x * xr);
                const sx2 = Math.max(sx1 + 1, Math.ceil((x + 1) * xr));
                const sy1 = Math.floor(y * yr);
                const sy2 = Math.max(sy1 + 1, Math.ceil((y + 1) * yr));
                let rSum = 0, gSum = 0, bSum = 0, aSum = 0, opaqueCnt = 0, totalCnt = 0;
                for (let sy = sy1; sy < sy2 && sy < wh; sy++) {
                    for (let sx = sx1; sx < sx2 && sx < ww; sx++) {
                        totalCnt++;
                        const si = (sy * ww + sx) * 4;
                        const pa = workBytes[si + 3];
                        aSum += pa;
                        if (pa > 0) {
                            rSum += workBytes[si] * pa;
                            gSum += workBytes[si + 1] * pa;
                            bSum += workBytes[si + 2] * pa;
                            opaqueCnt += pa;
                        }
                    }
                }
                if (opaqueCnt > 0) {
                    r = rSum / opaqueCnt;
                    g = gSum / opaqueCnt;
                    b = bSum / opaqueCnt;
                    a = aSum / totalCnt;
                }
            }

            if (a > 0 && (brightness !== 0 || contrast !== 0)) {
                r = cFactor * (r + bOffset - 128) + 128;
                g = cFactor * (g + bOffset - 128) + 128;
                b = cFactor * (b + bOffset - 128) + 128;
            }

            const di = (y * drawW + x) * 4;
            outBytes[di] = r < 0 ? 0 : (r > 255 ? 255 : Math.round(r));
            outBytes[di + 1] = g < 0 ? 0 : (g > 255 ? 255 : Math.round(g));
            outBytes[di + 2] = b < 0 ? 0 : (b > 255 ? 255 : Math.round(b));
            outBytes[di + 3] = a < 0 ? 0 : (a > 255 ? 255 : Math.round(a));
        }
    }

    _cachedScaled = { src: srcImgData, method, flip, drawW, drawH, brightness, contrast, data: outBytes };
    return outBytes;
}

export function getPanBounds() {
    if (!cgState.srcImageData) {
        return { minX: 0, maxX: 0, minY: 0, maxY: 0, drawW: 0, drawH: 0 };
    }
    const { W, H } = getCameoDims();
    const sw = Math.max(1, cgState.srcImageData.width);
    const sh = Math.max(1, cgState.srcImageData.height);
    const scale = Math.max(0.01, (cgState.zoomPct || 100) / 100);
    const drawW = Math.max(1, Math.round(sw * scale));
    const drawH = Math.max(1, Math.round(sh * scale));
    // Clamp offset so at least 1px of the imported image stays within the cameo border
    const maxX = Math.ceil((W + drawW) / 2);
    const minX = -maxX;
    const maxY = Math.ceil((H + drawH) / 2);
    const minY = -maxY;
    return { minX, maxX, minY, maxY, drawW, drawH };
}

function clampPanOffsets() {
    if (!cgState.srcImageData) {
        cgState.panX = 0;
        cgState.panY = 0;
        return;
    }
    const b = getPanBounds();
    cgState.panX = Math.max(b.minX, Math.min(b.maxX, Math.round(cgState.panX)));
    cgState.panY = Math.max(b.minY, Math.min(b.maxY, Math.round(cgState.panY)));
    cgState.elementOffsets.bg.x = cgState.panX;
    cgState.elementOffsets.bg.y = cgState.panY;

    const inpX = document.getElementById('cgInpPanX');
    const inpY = document.getElementById('cgInpPanY');
    if (inpX) {
        inpX.min = String(b.minX);
        inpX.max = String(b.maxX);
        inpX.value = String(cgState.panX);
    }
    if (inpY) {
        inpY.min = String(b.minY);
        inpY.max = String(b.maxY);
        inpY.value = String(cgState.panY);
    }
}

// ============================================================================
// TYPOGRAPHY & GLYPH ENGINE (Always Uppercase for Western/Cyrillic + CJK)
// ============================================================================
function isCjkCodepoint(cp) {
    return (
        (cp >= 0x2E80 && cp <= 0x9FFF) ||
        (cp >= 0xF900 && cp <= 0xFAFF) ||
        (cp >= 0x3000 && cp <= 0x303F) ||
        (cp >= 0xFF00 && cp <= 0xFFEF)
    );
}

function lineHasCjk(str) {
    for (let i = 0; i < str.length; i++) {
        if (isCjkCodepoint(str.codePointAt(i))) return true;
    }
    return false;
}

function lookupGlyph(cp, mixedMode) {
    const key = String(cp);
    if (mixedMode) {
        if (isCjkCodepoint(cp) && _cjkFontMap && _cjkFontMap.has(cp)) {
            return { g: _cjkFontMap.get(cp), isCjk: true };
        }
        if (CG_FONT_MIXED_ASCII[key]) {
            return { g: CG_FONT_MIXED_ASCII[key], isCjk: false };
        }
        if (_cjkFontMap && _cjkFontMap.has(cp)) {
            return { g: _cjkFontMap.get(cp), isCjk: true };
        }
    }
    if (CG_FONT_RA2[key]) {
        return { g: CG_FONT_RA2[key], isCjk: false };
    }
    if (_cjkFontMap && _cjkFontMap.has(cp)) {
        return { g: _cjkFontMap.get(cp), isCjk: true };
    }
    return null;
}

function layoutTextLine(rawText, W) {
    if (!rawText || !rawText.trim()) return null;
    // Always uppercase for Latin/Cyrillic as standard in RA2/TS
    const text = rawText.toUpperCase();
    const hasCjk = lineHasCjk(text);
    const chars = Array.from(text);
    const items = [];
    let totalW = 0;

    for (let i = 0; i < chars.length; i++) {
        const ch = chars[i];
        const cp = ch.codePointAt(0);
        if (cp === 32) {
            const adv = hasCjk ? 3 : 2;
            items.push({ space: true, dw: adv });
            totalW += adv;
            continue;
        }
        const found = lookupGlyph(cp, hasCjk);
        if (!found) continue;
        const [dw, gw, gh, ox, oy, rows] = found.g;
        items.push({ space: false, dw, gw, gh, ox, oy, rows, isCjk: found.isCjk });
        totalW += dw;
    }

    if (items.length > 0 && !items[items.length - 1].space) {
        const last = items[items.length - 1];
        totalW = totalW - last.dw + last.gw + Math.max(0, last.ox);
    }

    // Standard RA2/TS glyph height is 5px (Y=42..46 on bottom line, Y=36..40 on upper line)
    // CJK glyph height in Zpix 9pt is 8px (8x8 pixel grid, Y=39..46 on bottom line)
    const lineH = hasCjk ? 8 : 5;
    return { items, totalW, hasCjk, lineH };
}

function parseHexRgb(hex) {
    const clean = (hex || '#fcfcfc').replace('#', '');
    const n = parseInt(clean, 16) || 0xfcfcfc;
    return [(n >> 16) & 0xFF, (n >> 8) & 0xFF, n & 0xFF];
}

// ============================================================================
// OS SHP BUILDER 7 PROCEDURAL BEVELS + PDN LAYER BLENDING
// ============================================================================
function addBrightnessRect(data, isChromaBlue, W, H, x1, x2, y1, y2, delta, ox, oy) {
    const sx1 = Math.min(x1, x2) + ox, sx2 = Math.max(x1, x2) + ox;
    const sy1 = Math.min(y1, y2) + oy, sy2 = Math.max(y1, y2) + oy;
    for (let y = sy1; y <= sy2; y++) {
        if (y < 0 || y >= H) continue;
        for (let x = sx1; x <= sx2; x++) {
            if (x < 0 || x >= W) continue;
            const p = y * W + x;
            const idx = p * 4;
            data[idx] = Math.max(0, Math.min(255, data[idx] + delta));
            data[idx + 1] = Math.max(0, Math.min(255, data[idx + 1] + delta));
            data[idx + 2] = Math.max(0, Math.min(255, data[idx + 2] + delta));
            data[idx + 3] = 255;
            isChromaBlue[p] = 0;
        }
    }
}

function drawLightCameo2(data, isChromaBlue, W, H, value, x1, x2, y1, y2, ox, oy) {
    const xv = Math.max(1, Math.abs(x2 - x1));
    const yv = Math.max(1, Math.abs(y2 - y1));
    const step = Math.floor(value / (xv * yv));
    let v = value;
    for (let x = x1; x <= x2; x++) {
        for (let y = y1; y <= y2; y++) {
            addBrightnessRect(data, isChromaBlue, W, H, x, x, y, y, v, ox, oy);
            v = Math.max(0, v - step);
        }
    }
}

function applyProceduralBevel(data, isChromaBlue, W, H, style, ox, oy) {
    const val = 40;
    if (style === 'blade') {
        addBrightnessRect(data, isChromaBlue, W, H, 0, 0, 2, H - 3, -val, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, W - 2, W - 2, 1, H - 2, val, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 4, Math.min(W - 3, 33), 1, 2, val, ox, oy);
        if (34 < W) addBrightnessRect(data, isChromaBlue, W, H, 34, 34, 2, 2, val, ox, oy);
        for (let x = 1; x <= 3; x++) {
            for (let y = 1; y <= 2; y++) {
                if (!(x === 1 && y === 1)) {
                    addBrightnessRect(data, isChromaBlue, W, H, x, x, y, y, val * 2, ox, oy);
                }
            }
        }
    } else if (style === 'mix') {
        addBrightnessRect(data, isChromaBlue, W, H, W - 1, W - 1, 2, H - 3, -val, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 2, W - 3, H - 1, H - 1, -val, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 1, 1, 2, H - 2, val, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 2, W - 3, 1, 1, val, ox, oy);
    } else if (style === 'world_war') {
        addBrightnessRect(data, isChromaBlue, W, H, 1, 1, 2, H - 2, -val, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 2, W - 3, 1, 1, -val, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, W - 2, W - 2, 2, H - 3, val, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 2, W - 3, H - 2, H - 2, val, ox, oy);
    } else if (style === 'kravvitz_1') {
        drawLightCameo2(data, isChromaBlue, W, H, val * 2, 1, 1, 2, H - 2, ox, oy);
        drawLightCameo2(data, isChromaBlue, W, H, val * 2, 2, W - 2, 1, 1, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 2, 2, 2, 2, Math.floor((val * 3) / 2), ox, oy);
    } else if (style === 'kravvitz_2') {
        drawLightCameo2(data, isChromaBlue, W, H, val * 2, 1, 2, 2, H - 2, ox, oy);
        drawLightCameo2(data, isChromaBlue, W, H, val * 2, 3, W - 2, 1, 2, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 3, 3, 3, 3, val, ox, oy);
    } else if (style === 'ra1') {
        addBrightnessRect(data, isChromaBlue, W, H, 0, W - 2, 0, 0, 80, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 0, 0, 1, H - 2, 80, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 1, W - 1, H - 1, H - 1, -110, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, W - 1, W - 1, 1, H - 2, -110, ox, oy);
    } else if (style === 'td') {
        addBrightnessRect(data, isChromaBlue, W, H, 0, W - 2, 0, 0, 75, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 0, 0, 1, H - 2, 75, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, 0, W - 1, H - 1, H - 1, -140, ox, oy);
        addBrightnessRect(data, isChromaBlue, W, H, W - 1, W - 1, 0, H - 2, -140, ox, oy);
    }
}

function pdnFastScaleByte(a, b) {
    const t = a * b + 128;
    return (t + (t >> 8)) >> 8;
}

function blendPdnLayer(dstData, isChromaBlue, W, H, layerKey, opacityByte, blendMode, ox, oy, anchorMode, markOpaqueContent = true, overrideRole = null) {
    const override = (overrideRole && cgState.layerOverrides) ? cgState.layerOverrides[overrideRole] : null;
    const layer = override || _layerPixelsCache[layerKey];
    if (!layer) return;
    const lw = layer.width;
    const lh = layer.height;
    const src = layer.data;
    const effAnchor = override ? 'top_left' : anchorMode;

    for (let y = 0; y < H; y++) {
        const ly = (effAnchor === 'stretch') ? Math.floor(((y - oy) * lh) / H) : (y - oy);
        if (ly < 0 || ly >= lh) continue;

        for (let x = 0; x < W; x++) {
            let lx;
            if (effAnchor === 'stretch') {
                lx = Math.floor(((x - ox) * lw) / W);
            } else if (effAnchor === 'top_right') {
                lx = x - (W - lw) - ox;
            } else {
                lx = x - ox;
            }
            if (lx < 0 || lx >= lw) continue;

            const si = (ly * lw + lx) * 4;
            const sA = src[si + 3];
            if (sA === 0) continue;

            const effA = (opacityByte < 255) ? pdnFastScaleByte(sA, opacityByte) : sA;
            if (effA === 0) continue;

            const sR = src[si];
            const sG = src[si + 1];
            const sB = src[si + 2];
            if (blendMode === 'screen' && sR === 0 && sG === 0 && sB === 0) continue;

            const p = y * W + x;
            const di = p * 4;
            const dR = dstData[di];
            const dG = dstData[di + 1];
            const dB = dstData[di + 2];

            let rR = sR;
            let rG = sG;
            let rB = sB;
            if (blendMode === 'screen') {
                rR = 255 - pdnFastScaleByte(255 - dR, 255 - sR);
                rG = 255 - pdnFastScaleByte(255 - dG, 255 - sG);
                rB = 255 - pdnFastScaleByte(255 - dB, 255 - sB);
            }

            dstData[di] = ((rR * effA + dR * (255 - effA)) / 255) | 0;
            dstData[di + 1] = ((rG * effA + dG * (255 - effA)) / 255) | 0;
            dstData[di + 2] = ((rB * effA + dB * (255 - effA)) / 255) | 0;
            dstData[di + 3] = 255;

            if (markOpaqueContent) {
                isChromaBlue[p] = 0;
            }
        }
    }
}

function getCornerCoords(W, H) {
    return [
        [0, 0], [1, 0], [0, 1],
        [W - 2, 0], [W - 1, 0], [W - 1, 1],
        [0, H - 2], [0, H - 1], [1, H - 1],
        [W - 2, H - 1], [W - 1, H - 2], [W - 1, H - 1]
    ];
}

const RA2_METALLIC_ROWS = [
    [252, 252, 252], // Row 0 (Top)
    [248, 248, 248], // Row 1
    [212, 212, 212], // Row 2
    [173, 173, 173], // Row 3
    [165, 165, 165], // Row 4 (Bottom of 5px glyph)
    [165, 165, 165]  // Row 5 (Accented / 6px fallback)
];

const CN_DOME_VERT_ROWS = [
    [173, 173, 173],
    [212, 212, 212],
    [234, 234, 234],
    [249, 249, 249],
    [252, 252, 252],
    [252, 252, 252],
    [234, 234, 234],
    [212, 212, 212],
    [165, 165, 165]
];

function getLinePixelColor(line, relY, lineH, canvasX, W) {
    const style = line.style || 'ra2_grad';
    if (style === 'ra2_flat') {
        return [252, 252, 252];
    }
    if (style === 'ts_flat') {
        return [223, 223, 224];
    }
    if (style === 'custom') {
        return parseHexRgb(line.customColor);
    }
    if (style === 'cn_dome') {
        const idx = Math.max(0, Math.min(CN_DOME_VERT_ROWS.length - 1, Math.round((relY / Math.max(1, lineH - 1)) * (CN_DOME_VERT_ROWS.length - 1))));
        return CN_DOME_VERT_ROWS[idx];
    }
    // Default: 'ra2_grad'
    if (lineH <= 6) {
        const idx = Math.max(0, Math.min(RA2_METALLIC_ROWS.length - 1, relY));
        return RA2_METALLIC_ROWS[idx];
    }
    const tVal = Math.max(0, Math.min(1, relY / Math.max(1, lineH - 1)));
    const idx = Math.min(4, Math.floor(tVal * 4.99));
    return RA2_METALLIC_ROWS[idx];
}

function computeTextLineEntries(W, H) {
    // Assign vertical positions from bottom to top for all lines in cgState.textLines
    // so that Extra Line 1, Extra Line 2, etc. always sit at their respective rows
    // even if a lower line is left empty.
    const defaultLineH = cgState.gameType === 'ts' ? 6 : 5;
    const totalLines = cgState.textLines.length;
    const map = new Map();
    let curBottomY = H - 2; // 46 in 60x48, leaving 1px margin at Y = 47
    let prevYTop = H;

    for (let i = totalLines - 1; i >= 0; i--) {
        const line = cgState.textLines[i];
        const layout = layoutTextLine(line.text, W);
        const lineH = layout ? layout.lineH : defaultLineH;
        const baseY = curBottomY - lineH + 1;
        const adjBaseY = baseY + (line.offsetY || 0);
        const vis = isElementVisible(`text_${line.id}`);
        const yTop = Math.max(0, adjBaseY - 1);
        const yBot = Math.min(H - 1, adjBaseY + lineH, prevYTop - 1);
        if (layout && vis) {
            prevYTop = Math.min(prevYTop, yTop);
        }
        map.set(`text_${line.id}`, {
            id: `text_${line.id}`,
            line,
            layout,
            lineNum: totalLines - i,
            baseY: adjBaseY,
            yTop,
            yBot,
            visible: vis
        });
        curBottomY = baseY - 2; // 1px gap between lines (e.g. 42 -> 40, leaving Y=41 as gap)
    }
    return map;
}

function renderSingleTextLineEntry(dstData, isChromaBlue, W, H, entry) {
    if (!entry || !entry.layout || !entry.visible) return;
    const { line, layout, baseY, yTop, yBot } = entry;

    // 1. Render Text Background Darkness (1px above and 1px below each active line; deduplicated per row so adjacent lines never double-darken)
    const darkPct = Math.max(0, Math.min(100, Number(cgState.textBgDarkness) || 0));
    if (darkPct > 0 && yTop <= yBot) {
        const keep = 1 - (darkPct / 100);
        for (let y = yTop; y <= yBot; y++) {
            for (let x = 0; x < W; x++) {
                const p = y * W + x;
                const di = p * 4;
                dstData[di] = Math.round(dstData[di] * keep);
                dstData[di + 1] = Math.round(dstData[di + 1] * keep);
                dstData[di + 2] = Math.round(dstData[di + 2] * keep);
                dstData[di + 3] = 255;
            }
        }
    }

    // 2. Render text line (+1px right shadow first, then colored glyph pixels)
    let startX = Math.floor((W - layout.totalW) / 2);
    if (line.align === 'left') startX = 2;
    else if (line.align === 'right') startX = W - layout.totalW - 2;
    startX += (line.offsetX || 0);

    // Pass A: Shadow (+1px Right)
    if (cgState.textShadow) {
        let cx = startX;
        for (const item of layout.items) {
            if (item.space) {
                cx += item.dw;
                continue;
            }
            const gx0 = cx + Math.max(0, item.ox);
            const gy0 = baseY + (layout.hasCjk ? Math.max(0, 7 - (item.gh + (item.oy || 0))) : (item.gh > 5 ? -1 : 0));
            for (let r = 0; r < item.gh; r++) {
                const rowBits = item.rows[r];
                if (!rowBits) continue;
                const py = gy0 + r;
                if (py < 0 || py >= H) continue;
                for (let c = 0; c < item.gw; c++) {
                    if ((rowBits >> (item.gw - 1 - c)) & 1) {
                        const px = gx0 + c + 1; // +1px right shadow
                        if (px >= 0 && px < W) {
                            const p = py * W + px;
                            const di = p * 4;
                            dstData[di] = 0;
                            dstData[di + 1] = 0;
                            dstData[di + 2] = 0;
                            dstData[di + 3] = 255;
                            isChromaBlue[p] = 0;
                        }
                    }
                }
            }
            cx += item.dw;
        }
    }

    // Pass B: Foreground Glyph Pixels
    let cx = startX;
    for (const item of layout.items) {
        if (item.space) {
            cx += item.dw;
            continue;
        }
        const gx0 = cx + Math.max(0, item.ox);
        const gy0 = baseY + (layout.hasCjk ? Math.max(0, 7 - (item.gh + (item.oy || 0))) : (item.gh > 5 ? -1 : 0));
        for (let r = 0; r < item.gh; r++) {
            const rowBits = item.rows[r];
            if (!rowBits) continue;
            const py = gy0 + r;
            if (py < 0 || py >= H) continue;
            const relY = Math.max(0, py - baseY);
            for (let c = 0; c < item.gw; c++) {
                if ((rowBits >> (item.gw - 1 - c)) & 1) {
                    const px = gx0 + c;
                    if (px >= 0 && px < W) {
                        const [cr, cg, cb] = getLinePixelColor(line, relY, layout.lineH, px, W);
                        const p = py * W + px;
                        const di = p * 4;
                        dstData[di] = cr;
                        dstData[di + 1] = cg;
                        dstData[di + 2] = cb;
                        dstData[di + 3] = 255;
                        isChromaBlue[p] = 0;
                    }
                }
            }
        }
        cx += item.dw;
    }
}

function quantizeLinearEuclidean(r, g, b, palette, startIdx = 0) {
    let bestIdx = startIdx;
    let bestDist = Infinity;
    for (let i = startIdx; i < 256; i++) {
        const c = palette[i];
        if (!c) continue;
        const dr = r - c.r;
        const dg = g - c.g;
        const db = b - c.b;
        const d = dr * dr + dg * dg + db * db;
        if (d === 0) return i;
        if (d < bestDist) {
            bestDist = d;
            bestIdx = i;
        }
    }
    return bestIdx;
}

function cgQuantizeInfurium(srcRgb, W, H, x, y, palette) {
    const p = (y * W + x) * 4;
    const r = srcRgb[p];
    const g = srcRgb[p + 1];
    const b = srcRgb[p + 2];

    const c0 = palette[0];
    if (c0) {
        const isC0Blue = (c0.r <= 8 && c0.g <= 8 && c0.b >= 248);
        const isC0Magenta = (c0.r >= 248 && c0.g <= 8 && c0.b >= 248);
        if (isC0Blue && r === 0 && g === 0 && b === 255) return 0;
        if (isC0Magenta && r >= 250 && g === 0 && b >= 250) return 0;
    }
    const startIdx = 1;

    for (let i = startIdx; i < 256; i++) {
        const c = palette[i];
        if (!c) continue;
        if ((c.r === r && c.g === g && c.b === b) ||
            ((c.r & 0xFC) === r && (c.g & 0xFC) === g && (c.b & 0xFC) === b)) {
            return i;
        }
    }

    let bestDist = Infinity;
    let candidates = [];
    for (let i = startIdx; i < 256; i++) {
        const c = palette[i];
        if (!c) continue;
        const pr = c.r & 0xFC;
        const pg = c.g & 0xFC;
        const pb = c.b & 0xFC;
        const dr = r - pr;
        const dg = g - pg;
        const db = b - pb;
        const d = dr * dr + dg * dg + db * db;
        if (d < bestDist) {
            bestDist = d;
            candidates = [i];
        } else if (d === bestDist) {
            candidates.push(i);
        }
    }

    if (candidates.length === 0) return 0;
    if (candidates.length === 1) return candidates[0];

    // OS SHP Builder 3D RGB Infurium tie-breaker: 3x3 neighborhood distance
    const xMin = Math.max(0, x - 1);
    const xMax = Math.min(W - 1, x + 1);
    const yMin = Math.max(0, y - 1);
    const yMax = Math.min(H - 1, y + 1);

    let bestNeighDist = Infinity;
    let finalists = [];
    for (const idx of candidates) {
        const c = palette[idx];
        const pr = c.r & 0xFC;
        const pg = c.g & 0xFC;
        const pb = c.b & 0xFC;
        let t0 = 0;
        for (let ny = yMin; ny <= yMax; ny++) {
            for (let nx = xMin; nx <= xMax; nx++) {
                const np = (ny * W + nx) * 4;
                const dr = pr - srcRgb[np];
                const dg = pg - srcRgb[np + 1];
                const db = pb - srcRgb[np + 2];
                t0 += Math.sqrt(dr * dr + dg * dg + db * db);
            }
        }
        if (t0 < bestNeighDist - 1e-9) {
            bestNeighDist = t0;
            finalists = [idx];
        } else if (Math.abs(t0 - bestNeighDist) <= 1e-9) {
            finalists.push(idx);
        }
    }

    if (finalists.length === 1) return finalists[0];

    // Final Infurium lighting tie-breaker (threshold 221.7025033688163)
    let tn = 0;
    let ncount = 0;
    for (let ny = yMin; ny <= yMax; ny++) {
        for (let nx = xMin; nx <= xMax; nx++) {
            const np = (ny * W + nx) * 4;
            const nr = srcRgb[np];
            const ng = srcRgb[np + 1];
            const nb = srcRgb[np + 2];
            tn += Math.sqrt(nr * nr + ng * ng + nb * nb);
            ncount++;
        }
    }
    tn /= Math.max(1, ncount);
    const isLight = tn >= 221.7025033688163;
    const targetVal = isLight ? 255 : 0;

    let chosenIdx = finalists[0];
    let bestLightDist = Infinity;
    for (const idx of finalists) {
        const c = palette[idx];
        const dr = targetVal - (c.r & 0xFC);
        const dg = targetVal - (c.g & 0xFC);
        const db = targetVal - (c.b & 0xFC);
        const d = dr * dr + dg * dg + db * db;
        if (d < bestLightDist) {
            bestLightDist = d;
            chosenIdx = idx;
        }
    }
    return chosenIdx;
}

export async function compositeCameoCanvas() {
    await preloadAllLayers();

    // Ensure CJK font is decoded if any text line has CJK characters
    const needsCjk = cgState.textLines.some(l => lineHasCjk(l.text || ''));
    if (needsCjk) {
        await ensureCjkFontDecoded();
    }

    const { W, H } = getCameoDims();
    const imgData = new ImageData(W, H);
    const dst = imgData.data;
    const isChromaBlue = new Uint8Array(W * H);

    // 1. Base Background: Pure solid blue RGB(0, 0, 255)
    for (let p = 0; p < W * H; p++) {
        const di = p * 4;
        dst[di] = 0;
        dst[di + 1] = 0;
        dst[di + 2] = 255;
        dst[di + 3] = 255;
        isChromaBlue[p] = 1;
    }

    // 2..5. Composite Active Elements from Bottom-Most Layer to Top-Most Layer (respecting custom drag-and-drop layer order)
    const canonicalOrder = ensureCanonicalElementOrder();
    const bottomToTopIds = canonicalOrder.slice().reverse();
    const textEntriesMap = computeTextLineEntries(W, H);
    let preGlassRgb = null;

    for (const elId of bottomToTopIds) {
        if (elId === 'unit') {
            if (cgState.srcImageData && isElementVisible('unit')) {
                clampPanOffsets();
                const { drawW, drawH } = getPanBounds();
                const scaledBytes = getScaledUnitBuffer(
                    cgState.srcImageData,
                    drawW,
                    drawH,
                    cgState.resample,
                    cgState.flip,
                    cgState.brightness,
                    cgState.contrast
                );
                const baseX = Math.round((W - drawW) / 2) + cgState.panX;
                const baseY = Math.round((H - drawH) / 2) + cgState.panY;

                for (let sy = 0; sy < drawH; sy++) {
                    const dy = baseY + sy;
                    if (dy < 0 || dy >= H) continue;
                    for (let sx = 0; sx < drawW; sx++) {
                        const dx = baseX + sx;
                        if (dx < 0 || dx >= W) continue;
                        const si = (sy * drawW + sx) * 4;
                        const sA = scaledBytes[si + 3];
                        if (sA === 0) continue;
                        const sR = scaledBytes[si];
                        const sG = scaledBytes[si + 1];
                        const sB = scaledBytes[si + 2];
                        // Treat pure chroma-key blue (0,0,255) in imported frame as transparent background
                        if (sR === 0 && sG === 0 && sB === 255) continue;

                        const p = dy * W + dx;
                        const di = p * 4;
                        const a = sA / 255;
                        dst[di] = Math.round(sR * a + dst[di] * (1 - a));
                        dst[di + 1] = Math.round(sG * a + dst[di + 1] * (1 - a));
                        dst[di + 2] = Math.round(sB * a + dst[di + 2] * (1 - a));
                        dst[di + 3] = 255;
                        isChromaBlue[p] = 0;
                    }
                }
            }
        } else if (elId === 'fake') {
            if (cgState.fakeBanner && cgState.fakeBanner !== 'none' && isElementVisible('fake')) {
                const off = cgState.elementOffsets.fake || { x: 0, y: 0 };
                blendPdnLayer(dst, isChromaBlue, W, H, cgState.fakeBanner, 255, 'normal', off.x, off.y, 'stretch', true, 'fake');
            }
        } else if (elId === 'upgrade') {
            if (cgState.badgeUpgrade && isElementVisible('upgrade')) {
                const off = cgState.elementOffsets.upgrade || { x: 0, y: 0 };
                blendPdnLayer(dst, isChromaBlue, W, H, 'badge_upgrade', 255, 'normal', off.x, off.y, 'top_left', true, 'upgrade');
            }
        } else if (elId === 'veteran') {
            if (cgState.veteran && cgState.veteran !== 'none' && isElementVisible('veteran')) {
                const off = cgState.elementOffsets.veteran || { x: 0, y: 0 };
                const anchor = cgState.veteran.includes('right') ? 'top_right' : 'top_left';
                blendPdnLayer(dst, isChromaBlue, W, H, cgState.veteran, 255, 'normal', off.x, off.y, anchor, true, 'veteran');
            }
        } else if (elId === 'amphibious') {
            if (cgState.badgeAmphibious && isElementVisible('amphibious')) {
                const off = cgState.elementOffsets.amphibious || { x: 0, y: 0 };
                blendPdnLayer(dst, isChromaBlue, W, H, 'badge_amphibious', 255, 'normal', off.x, off.y, 'top_right', true, 'amphibious');
            }
        } else if (elId === 'jumpjet') {
            if (cgState.badgeJumpjet && isElementVisible('jumpjet')) {
                const off = cgState.elementOffsets.jumpjet || { x: 0, y: 0 };
                blendPdnLayer(dst, isChromaBlue, W, H, 'badge_jumpjet', 255, 'normal', off.x, off.y, 'top_right', true, 'jumpjet');
            }
        } else if (elId.startsWith('text_')) {
            const entry = textEntriesMap.get(elId);
            if (entry) {
                renderSingleTextLineEntry(dst, isChromaBlue, W, H, entry);
            }
        } else if (elId === 'glass') {
            preGlassRgb = new Uint8ClampedArray(dst);
            if (isElementVisible('glass') && cgState.glass && cgState.glass !== 'none') {
                const off = cgState.elementOffsets.glass || { x: 0, y: 0 };
                if (cgState.glass === 'another_glass') {
                    blendPdnLayer(dst, isChromaBlue, W, H, 'glass_subtle', 255, 'screen', off.x, off.y, 'stretch', false);
                    blendPdnLayer(dst, isChromaBlue, W, H, 'border_3d', 255, 'normal', off.x, off.y, 'stretch', true);
                } else if (cgState.glass === 'ra2_glass') {
                    blendPdnLayer(dst, isChromaBlue, W, H, 'glass_classic', 255, 'screen', off.x, off.y, 'stretch', false);
                    blendPdnLayer(dst, isChromaBlue, W, H, 'border_3d', 255, 'normal', off.x, off.y, 'stretch', true);
                } else if (cgState.glass === 'ra2_edges') {
                    blendPdnLayer(dst, isChromaBlue, W, H, 'border_3d', 255, 'normal', off.x, off.y, 'stretch', true);
                } else {
                    applyProceduralBevel(dst, isChromaBlue, W, H, cgState.glass, off.x, off.y);
                }
            }
        }
    }
    if (!preGlassRgb) {
        preGlassRgb = new Uint8ClampedArray(dst);
    }

    // 7. Dark Corners Anti-Aliasing (27% Opacity Layer 36 from PDN)
    if (cgState.darkCorners) {
        blendPdnLayer(dst, isChromaBlue, W, H, 'dark_corners', 69, 'normal', 0, 0, 'stretch', false);
    }

    // 8. Palette Quantization (OS SHP Builder 3D RGB Infurium across indices 0..255) & Corner Mask
    const pal = getTargetPalette();
    const indexedFrame = new Uint8Array(W * H);
    const hasValidCustomPal = Boolean(
        (_customPalette && _customPalette.length === 256 && _customPalette.some(Boolean)) ||
        (state && state.palette && state.palette.length === 256 && state.palette.some(Boolean))
    );
    const restrictPalette = (
        cgState.paletteMode === 'ra2' ||
        cgState.paletteMode === 'ts' ||
        (cgState.paletteMode === 'custom' && hasValidCustomPal)
    );

    const srcRgb = new Uint8ClampedArray(dst);
    for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
            const p = y * W + x;
            const di = p * 4;
            const idx = cgQuantizeInfurium(srcRgb, W, H, x, y, pal);
            indexedFrame[p] = idx;
            if (restrictPalette) {
                const c = pal[idx];
                if (c) {
                    dst[di] = c.r;
                    dst[di + 1] = c.g;
                    dst[di + 2] = c.b;
                    dst[di + 3] = 255;
                }
            }
        }
    }

    // Apply 12-Pixel Corner Mask
    if (cgState.cornerMask && cgState.cornerMask !== 'none') {
        const corners = getCornerCoords(W, H);
        for (const [cx, cy] of corners) {
            const p = cy * W + cx;
            const di = p * 4;
            if (cgState.cornerMask === 'shp_blue') {
                // Pure Blue RGB(0, 0, 255) on preview and Index 0 in SHP
                dst[di] = 0;
                dst[di + 1] = 0;
                dst[di + 2] = 255;
                dst[di + 3] = 255;
                indexedFrame[p] = 0;
            } else if (cgState.cornerMask === 'pcx_magenta') {
                dst[di] = 253;
                dst[di + 1] = 0;
                dst[di + 2] = 253;
                dst[di + 3] = 255;
                indexedFrame[p] = 0;
            } else if (cgState.cornerMask === 'black') {
                dst[di] = 0;
                dst[di + 1] = 0;
                dst[di + 2] = 0;
                dst[di + 3] = 255;
                indexedFrame[p] = quantizeLinearEuclidean(0, 0, 0, pal);
            } else if (cgState.cornerMask === 'alpha0') {
                dst[di] = 0;
                dst[di + 1] = 0;
                dst[di + 2] = 0;
                dst[di + 3] = 0;
                indexedFrame[p] = 0;
            }
        }
    }

    cgState.lastCompositedImageData = imgData;
    cgState.lastIndexedFrame = indexedFrame;
    cgState.lastActivePalette = pal;
    return { imgData, indexedFrame, pal, W, H, isChromaBlue, preGlassRgb };
}


// ============================================================================
// PREVIEW RENDERING, ZOOM BAR & DYNAMIC UI LISTS
// ============================================================================
export function updatePreviewZoomUI() {
    const inp = document.getElementById('inpCgPreviewZoom');
    const bar = document.getElementById('cgPreviewZoomBar');
    const valEl = document.getElementById('cgPreviewZoomVal');
    const z = Math.max(50, Math.min(2000, Math.round(cgState.previewZoomPct || 100)));
    cgState.previewZoomPct = z;
    if (inp) inp.value = String(z);
    if (valEl) valEl.textContent = `${z}%`;
    if (bar) {
        const min = inp ? (parseFloat(inp.min) || 50) : 50;
        const max = inp ? (parseFloat(inp.max) || 2000) : 2000;
        const pct = Math.max(0, Math.min(100, ((z - min) / (max - min)) * 100));
        bar.style.width = `${pct}%`;
    }
}

export async function updateCameoPreview() {
    const { imgData, W, H } = await compositeCameoCanvas();
    const previewCanvas = document.getElementById('cgPreviewCanvas');
    if (!previewCanvas) return;

    if (previewCanvas.width !== W) previewCanvas.width = W;
    if (previewCanvas.height !== H) previewCanvas.height = H;

    const ctx = previewCanvas.getContext('2d');
    ctx.putImageData(imgData, 0, 0);

    updatePreviewZoomUI();
    const scale = (cgState.previewZoomPct || 100) / 100;
    previewCanvas.style.width = `${Math.max(1, Math.round(W * scale))}px`;
    previewCanvas.style.height = `${Math.max(1, Math.round(H * scale))}px`;

    renderActiveElementsListUI();
    saveCameoStateToStorage();
}

export function renderTextLinesUI() {
    const container = document.getElementById('cgTextLinesContainer');
    if (!container) return;
    container.innerHTML = '';

    // cgState.textLines is ordered from top to bottom.
    // Placeholders match the left-panel naming: LINE 1 (bottom-most), LINE 2, LINE 3... upwards.
    const total = cgState.textLines.length;
    cgState.textLines.forEach((line, idx) => {
        const isRemovable = idx < total - 2;
        const lineNum = total - idx;
        const row = document.createElement('div');
        row.style.cssText = 'display:flex; flex-wrap:wrap; gap:6px; align-items:center;';

        const inp = document.createElement('input');
        inp.type = 'text';
        inp.className = 'seq-input';
        inp.style.cssText = 'flex:2 1 130px; min-width:110px; height:26px; padding:0 8px; font-size:11px;';
        inp.maxLength = 24;
        inp.placeholder = `${t('cg_el_line') || 'LINE'} ${lineNum}`;
        inp.value = line.text || '';
        inp.style.textTransform = inp.value ? 'uppercase' : 'none';
        inp.addEventListener('input', () => {
            line.text = inp.value;
            inp.style.textTransform = inp.value ? 'uppercase' : 'none';
            updateCameoPreview();
        });

        const selStyle = document.createElement('select');
        selStyle.className = 'seq-input';
        selStyle.style.cssText = 'flex:1.2 1 135px; min-width:120px; height:26px; padding:0 8px; font-size:11px;';
        const styleOpts = [
            { value: 'ra2_flat', label: t('cg_opt_txt_ra2_flat') || 'Flat Color (RA2)' },
            { value: 'ra2_grad', label: t('cg_opt_txt_ra2_grad') || 'Gradient (RA2)' },
            { value: 'ts_flat', label: t('cg_opt_txt_ts_flat') || 'Flat Color (TS)' },
            { value: 'cn_dome', label: t('cg_opt_txt_cn_dome') || 'Gradient Wave' },
            { value: 'custom', label: t('cg_opt_txt_custom') || 'Custom Color...' }
        ];
        for (const o of styleOpts) {
            const opt = document.createElement('option');
            opt.value = o.value;
            opt.textContent = o.label;
            if (line.style === o.value) opt.selected = true;
            selStyle.appendChild(opt);
        }

        const inpColor = document.createElement('input');
        inpColor.type = 'color';
        inpColor.value = line.customColor || '#FCFCFC';
        inpColor.style.cssText = `width:28px; height:26px; padding:0; border:1px solid #2d3748; background:transparent; cursor:pointer; display:${line.style === 'custom' ? 'block' : 'none'};`;
        inpColor.addEventListener('input', () => {
            line.customColor = inpColor.value;
            updateCameoPreview();
        });

        selStyle.addEventListener('change', () => {
            line.style = selStyle.value;
            inpColor.style.display = line.style === 'custom' ? 'block' : 'none';
            updateCameoPreview();
        });

        const selAlign = document.createElement('select');
        selAlign.className = 'seq-input';
        selAlign.style.cssText = 'flex:0.8 1 90px; min-width:80px; height:26px; padding:0 8px; font-size:11px;';
        const alignOpts = [
            { value: 'left', label: t('cg_opt_align_left') || 'Left' },
            { value: 'center', label: t('cg_opt_align_center') || 'Center' },
            { value: 'right', label: t('cg_opt_align_right') || 'Right' }
        ];
        for (const o of alignOpts) {
            const opt = document.createElement('option');
            opt.value = o.value;
            opt.textContent = o.label;
            if (line.align === o.value) opt.selected = true;
            selAlign.appendChild(opt);
        }
        selAlign.addEventListener('change', () => {
            line.align = selAlign.value;
            updateCameoPreview();
        });

        const btnDel = document.createElement('button');
        btnDel.type = 'button';
        btnDel.className = 'btn btn-danger';
        btnDel.style.cssText = `height:26px; width:26px; padding:0; font-size:11px; display:flex; align-items:center; justify-content:center; visibility:${isRemovable ? 'visible' : 'hidden'};`;
        btnDel.textContent = '✕';
        btnDel.title = t('cg_tt_remove_line') || 'Remove text line';
        if (isRemovable) {
            btnDel.addEventListener('click', () => {
                const targetId = `text_${line.id}`;
                if (cgState.selectedElementId === targetId) {
                    cgState.selectedElementId = null;
                }
                cgState.textLines.splice(idx, 1);
                renderTextLinesUI();
                renderActiveElementsListUI();
                updateCameoPreview();
            });
        }

        row.appendChild(inp);
        row.appendChild(selStyle);
        row.appendChild(inpColor);
        row.appendChild(selAlign);
        row.appendChild(btnDel);
        container.appendChild(row);
    });
}

function getActiveElementsList() {
    const byId = new Map();

    // 1. Glass Reflection / 3D Frame Bevel (Top-most by default)
    if (cgState.glass && cgState.glass !== 'none') {
        const off = cgState.elementOffsets.glass || { x: 0, y: 0 };
        byId.set('glass', {
            id: 'glass',
            label: t('cg_lbl_glass') ? t('cg_lbl_glass').replace(':', '') : 'Glass Reflection',
            x: off.x,
            y: off.y,
            reset: () => { cgState.elementOffsets.glass = { x: 0, y: 0 }; }
        });
    }

    // 2. Text Lines (LINE 1, LINE 2, LINE 3... where LINE 1 is the bottom-most line in the right section)
    const totalTextLines = cgState.textLines.length;
    for (let idx = totalTextLines - 1; idx >= 0; idx--) {
        const line = cgState.textLines[idx];
        const lineNum = totalTextLines - idx;
        const id = `text_${line.id}`;
        byId.set(id, {
            id,
            label: `${t('cg_el_line') || 'LINE'} ${lineNum}`,
            x: line.offsetX || 0,
            y: line.offsetY || 0,
            reset: () => {
                line.offsetX = 0;
                line.offsetY = 0;
            }
        });
    }

    // 3. Badges (Jumpjet, Amphibious, Chevron, Upgrade)
    if (cgState.badgeJumpjet) {
        const off = cgState.elementOffsets.jumpjet || { x: 0, y: 0 };
        byId.set('jumpjet', {
            id: 'jumpjet',
            label: t('cg_chk_badge_jumpjet') || 'Jumpjet Icon',
            x: off.x,
            y: off.y,
            reset: () => { cgState.elementOffsets.jumpjet = { x: 0, y: 0 }; }
        });
    }
    if (cgState.badgeAmphibious) {
        const off = cgState.elementOffsets.amphibious || { x: 0, y: 0 };
        byId.set('amphibious', {
            id: 'amphibious',
            label: t('cg_chk_badge_amphibious') || 'Amphibious Icon',
            x: off.x,
            y: off.y,
            reset: () => { cgState.elementOffsets.amphibious = { x: 0, y: 0 }; }
        });
    }
    if (cgState.veteran && cgState.veteran !== 'none') {
        const off = cgState.elementOffsets.veteran || { x: 0, y: 0 };
        byId.set('veteran', {
            id: 'veteran',
            label: t('cg_el_veteran') || 'Chevron',
            x: off.x,
            y: off.y,
            reset: () => { cgState.elementOffsets.veteran = { x: 0, y: 0 }; }
        });
    }
    if (cgState.badgeUpgrade) {
        const off = cgState.elementOffsets.upgrade || { x: 0, y: 0 };
        byId.set('upgrade', {
            id: 'upgrade',
            label: t('cg_chk_badge_upgrade') || 'Upgrade Badge',
            x: off.x,
            y: off.y,
            reset: () => { cgState.elementOffsets.upgrade = { x: 0, y: 0 }; }
        });
    }

    // 4. Fake Structure Band
    if (cgState.fakeBanner && cgState.fakeBanner !== 'none') {
        const off = cgState.elementOffsets.fake || { x: 0, y: 0 };
        byId.set('fake', {
            id: 'fake',
            label: t('cg_el_fake_band') || 'Fake Structure Band',
            x: off.x,
            y: off.y,
            reset: () => { cgState.elementOffsets.fake = { x: 0, y: 0 }; }
        });
    }

    // 5. Background / Unit Image (Bottom-most by default)
    if (cgState.srcImageData) {
        byId.set('unit', {
            id: 'unit',
            label: t('cg_el_background_img') || 'Background Image',
            x: cgState.panX || 0,
            y: cgState.panY || 0,
            reset: () => {
                cgState.panX = 0;
                cgState.panY = 0;
                syncImageTransformInputs();
            }
        });
    }

    const canonicalOrder = ensureCanonicalElementOrder();
    const items = [];
    for (const id of canonicalOrder) {
        if (byId.has(id)) {
            items.push(byId.get(id));
        }
    }

    // Prune visibility overrides for elements no longer in the active list so newly added/enabled elements always start visible
    if (cgState.hiddenElements) {
        const activeIds = new Set(items.map(i => i.id));
        for (const k of Object.keys(cgState.hiddenElements)) {
            if (!activeIds.has(k)) {
                delete cgState.hiddenElements[k];
            }
        }
    }

    return items;
}

let _draggedActiveElementId = null;

function reorderActiveElement(draggedId, targetId, placeAfter) {
    if (!draggedId || !targetId || draggedId === targetId) return;
    const activeItems = getActiveElementsList();
    const activeIds = activeItems.map(i => i.id);
    const fromIdx = activeIds.indexOf(draggedId);
    const targetIdx = activeIds.indexOf(targetId);
    if (fromIdx === -1 || targetIdx === -1) return;

    activeIds.splice(fromIdx, 1);
    const newTargetIdx = activeIds.indexOf(targetId);
    const insertIdx = placeAfter ? (newTargetIdx + 1) : newTargetIdx;
    activeIds.splice(insertIdx, 0, draggedId);

    const canonical = ensureCanonicalElementOrder().slice();
    const cFrom = canonical.indexOf(draggedId);
    if (cFrom !== -1) canonical.splice(cFrom, 1);

    if (insertIdx < activeIds.length - 1) {
        const nextActiveId = activeIds[insertIdx + 1];
        const nextPos = canonical.indexOf(nextActiveId);
        if (nextPos !== -1) {
            canonical.splice(nextPos, 0, draggedId);
        } else {
            canonical.push(draggedId);
        }
    } else if (insertIdx > 0) {
        const prevActiveId = activeIds[insertIdx - 1];
        const prevPos = canonical.indexOf(prevActiveId);
        if (prevPos !== -1) {
            canonical.splice(prevPos + 1, 0, draggedId);
        } else {
            canonical.push(draggedId);
        }
    } else {
        canonical.unshift(draggedId);
    }

    cgState.elementOrder = canonical;
    updateCameoPreview();
}

export function renderActiveElementsListUI() {
    const listEl = document.getElementById('cgActiveElementsList');
    if (!listEl) return;
    listEl.innerHTML = '';

    const items = getActiveElementsList();
    if (cgState.selectedElementId && !items.some(i => i.id === cgState.selectedElementId)) {
        cgState.selectedElementId = null;
    }

    for (const item of items) {
        const isSelected = cgState.selectedElementId === item.id;
        const isVis = isElementVisible(item.id);
        const row = document.createElement('div');
        row.style.cssText = 'display:flex; align-items:center; gap:5px; border-top:2px solid transparent; border-bottom:2px solid transparent; border-radius:3px;';
        row.draggable = true;
        row.dataset.elementId = item.id;

        row.addEventListener('dragstart', (e) => {
            _draggedActiveElementId = item.id;
            row.style.opacity = '0.45';
            if (e.dataTransfer) {
                e.dataTransfer.effectAllowed = 'move';
                try { e.dataTransfer.setData('text/plain', item.id); } catch (_) {}
            }
        });

        row.addEventListener('dragend', () => {
            _draggedActiveElementId = null;
            row.style.opacity = '1';
            row.style.borderTopColor = 'transparent';
            row.style.borderBottomColor = 'transparent';
        });

        row.addEventListener('dragover', (e) => {
            if (!_draggedActiveElementId || _draggedActiveElementId === item.id) return;
            e.preventDefault();
            e.stopPropagation();
            if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
            const rect = row.getBoundingClientRect();
            const isAfter = (e.clientY - rect.top) > (rect.height / 2);
            row.style.borderTopColor = isAfter ? 'transparent' : '#38bdf8';
            row.style.borderBottomColor = isAfter ? '#38bdf8' : 'transparent';
        });

        row.addEventListener('dragleave', () => {
            row.style.borderTopColor = 'transparent';
            row.style.borderBottomColor = 'transparent';
        });

        row.addEventListener('drop', (e) => {
            if (!_draggedActiveElementId) return;
            e.preventDefault();
            e.stopPropagation();
            const draggedId = _draggedActiveElementId;
            _draggedActiveElementId = null;
            const rect = row.getBoundingClientRect();
            const placeAfter = (e.clientY - rect.top) > (rect.height / 2);
            row.style.borderTopColor = 'transparent';
            row.style.borderBottomColor = 'transparent';
            reorderActiveElement(draggedId, item.id, placeAfter);
        });

        const btnToggle = document.createElement('button');
        btnToggle.type = 'button';
        btnToggle.className = 'btn';
        btnToggle.title = t('cg_tt_drag_reorder_layer') || 'Click to select for canvas dragging; drag row to reorder layer priority';
        btnToggle.style.cssText = `flex:1; height:24px; padding:0 8px; font-size:11px; display:flex; align-items:center; justify-content:space-between; text-align:left; border:1px solid ${isSelected ? '#38bdf8' : '#2d3748'}; background:${isSelected ? 'rgba(56, 189, 248, 0.18)' : '#1a1f2c'}; color:${isSelected ? '#38bdf8' : '#e2e8f0'}; font-weight:${isSelected ? '700' : '400'}; opacity:${isVis ? '1' : '0.55'}; cursor:grab;`;

        const leftWrap = document.createElement('span');
        leftWrap.style.cssText = 'display:flex; align-items:center; gap:5px; overflow:hidden; min-width:0;';

        const spanHandle = document.createElement('span');
        spanHandle.textContent = '⠿';
        spanHandle.style.cssText = 'opacity:0.55; font-size:11px; flex-shrink:0; user-select:none;';

        const spanName = document.createElement('span');
        spanName.style.cssText = 'overflow:hidden; text-overflow:ellipsis; white-space:nowrap;';
        spanName.textContent = item.label;

        leftWrap.appendChild(spanHandle);
        leftWrap.appendChild(spanName);

        const spanPos = document.createElement('span');
        spanPos.style.cssText = 'font-size:10px; opacity:0.8; margin-left:6px; flex-shrink:0;';
        spanPos.textContent = `(${item.x >= 0 ? '+' + item.x : item.x}, ${item.y >= 0 ? '+' + item.y : item.y})`;

        btnToggle.appendChild(leftWrap);
        btnToggle.appendChild(spanPos);

        btnToggle.addEventListener('click', () => {
            cgState.selectedElementId = (cgState.selectedElementId === item.id) ? null : item.id;
            renderActiveElementsListUI();
        });

        const btnVis = document.createElement('button');
        btnVis.type = 'button';
        btnVis.className = 'btn';
        btnVis.style.cssText = `width:24px; height:24px; padding:0; font-size:12px; display:flex; align-items:center; justify-content:center; flex-shrink:0; opacity:${isVis ? '1' : '0.55'};`;
        btnVis.textContent = isVis ? '👁️' : '🚫';
        btnVis.title = t('cg_tt_toggle_element_vis') || 'Show / hide element in preview';
        btnVis.addEventListener('click', () => {
            if (!cgState.hiddenElements) cgState.hiddenElements = {};
            cgState.hiddenElements[item.id] = isVis;
            updateCameoPreview();
        });

        const btnReset = document.createElement('button');
        btnReset.type = 'button';
        btnReset.className = 'btn';
        btnReset.style.cssText = 'width:24px; height:24px; padding:0; font-size:12px; display:flex; align-items:center; justify-content:center; flex-shrink:0;';
        btnReset.textContent = '↺';
        btnReset.title = t('cg_tt_reset_element_pos') || 'Restore default position';
        btnReset.disabled = (item.x === 0 && item.y === 0);
        btnReset.addEventListener('click', () => {
            item.reset();
            updateCameoPreview();
        });

        row.appendChild(btnToggle);
        row.appendChild(btnVis);
        row.appendChild(btnReset);
        listEl.appendChild(row);
    }
}


// ============================================================================
// STATE SYNCHRONIZATION, GAME TYPE PRESETS & IMAGE LOADING
// ============================================================================
export function syncImageTransformInputs() {
    const hasImg = !!cgState.srcImageData;
    const row = document.getElementById('cgImageTransformRow');
    if (row) {
        if (hasImg) row.classList.remove('disabled-ui');
        else row.classList.add('disabled-ui');
    }
    clampPanOffsets();
    const inpZ = document.getElementById('cgInpZoomPct');
    const inpB = document.getElementById('cgInpBrightness');
    const inpC = document.getElementById('cgInpContrast');

    if (inpZ) { inpZ.value = String(cgState.zoomPct || 100); inpZ.disabled = !hasImg; }
    if (inpB) { inpB.value = String(cgState.brightness || 0); inpB.disabled = !hasImg; }
    if (inpC) { inpC.value = String(cgState.contrast || 0); inpC.disabled = !hasImg; }

    const stepBtnIds = [
        'btnCgZoomDec', 'btnCgZoomInc',
        'btnCgBrightDec', 'btnCgBrightInc',
        'btnCgContrastDec', 'btnCgContrastInc',
        'cgBtnResetTransform'
    ];
    for (const id of stepBtnIds) {
        const b = document.getElementById(id);
        if (b) b.disabled = !hasImg;
    }
}

export function syncUiFromState() {
    const setVal = (id, v) => {
        const el = document.getElementById(id);
        if (el) el.value = String(v);
    };
    const setChk = (id, v) => {
        const el = document.getElementById(id);
        if (el) el.checked = !!v;
    };

    setVal('cgSelGameType', cgState.gameType);
    setChk('cgChkShowGrid', cgState.showGrid);
    setVal('cgSelPaletteMode', cgState.paletteMode);
    setVal('cgSelResample', cgState.resample);
    setVal('cgSelFlip', cgState.flip);
    setVal('cgInpTextBgDark', cgState.textBgDarkness);
    setChk('cgChkTextShadow', cgState.textShadow);
    setVal('cgSelGlass', cgState.glass);
    setVal('cgSelBevel', cgState.bevel);
    setVal('cgSelCornerMask', cgState.cornerMask);
    setVal('cgSelVeteran', cgState.veteran);
    setVal('cgSelFakeBanner', cgState.fakeBanner);
    setChk('cgChkDarkCorners', cgState.darkCorners);
    setChk('cgChkBadgeUpgrade', cgState.badgeUpgrade);
    setChk('cgChkBadgeAmphibious', cgState.badgeAmphibious);
    setChk('cgChkBadgeJumpjet', cgState.badgeJumpjet);

    const boxCustomPal = document.getElementById('cgBoxCustomPalette');
    if (boxCustomPal) {
        boxCustomPal.style.display = (cgState.paletteMode === 'custom') ? 'flex' : 'none';
    }
    const lblCustomPal = document.getElementById('cgCustomPalName');
    if (lblCustomPal) {
        if (_customPaletteName) {
            lblCustomPal.textContent = _customPaletteName;
            lblCustomPal.removeAttribute('data-i18n');
        } else {
            lblCustomPal.setAttribute('data-i18n', 'lbl_select_palette');
            lblCustomPal.textContent = t('lbl_select_palette') || 'Select Palette...';
        }
    }

    const lblSource = document.getElementById('cgLblSourceInfo');
    if (lblSource) {
        if (cgState.srcImageData) {
            lblSource.textContent = cgState.srcLabel || `${cgState.srcImageData.width}x${cgState.srcImageData.height}`;
            lblSource.removeAttribute('data-i18n');
        } else {
            lblSource.setAttribute('data-i18n', 'cg_lbl_no_image');
            lblSource.textContent = t('cg_lbl_no_image') || 'No image loaded';
        }
    }

    syncImageTransformInputs();
    updatePreviewZoomUI();
    renderTextLinesUI();
    renderActiveElementsListUI();
    saveCameoStateToStorage();
}

export function applyGameTypeDefaults(gameType) {
    const isTs = (gameType === 'ts');
    cgState.gameType = isTs ? 'ts' : 'ra2';
    if (cgState.paletteMode === 'ra2' || cgState.paletteMode === 'ts') {
        cgState.paletteMode = isTs ? 'ts' : 'ra2';
    }
    cgState.textBgDarkness = isTs ? 0 : 38;
    cgState.textShadow = true;
    cgState.glass = isTs ? 'none' : 'another_glass';
    cgState.bevel = isTs ? 'none' : 'ra2_edges';
    cgState.cornerMask = isTs ? 'none' : 'shp_blue';
    cgState.darkCorners = !isTs;

    // Update text line styles and alignments to match the selected game's standard
    const total = cgState.textLines.length;
    cgState.textLines.forEach((line, idx) => {
        if (isTs) {
            line.style = 'ts_flat';
            line.align = 'left';
        } else {
            line.style = (idx === total - 1) ? 'ra2_grad' : 'ra2_flat';
            line.align = 'center';
        }
    });

    clampPanOffsets();
    syncUiFromState();
    updateCameoPreview();
}

export function resetAllWindowState() {
    invalidateScaleCache();
    _customPalette = null;
    _customPaletteName = '';
    cgState.gameType = 'ra2';
    cgState.previewZoomPct = 100;
    cgState.showGrid = false;
    cgState.srcImageData = null;
    cgState.srcLabel = '';
    cgState.paletteMode = 'full';
    cgState.resample = 'smart';
    cgState.flip = 'none';
    cgState.panX = 0;
    cgState.panY = 0;
    cgState.zoomPct = 100;
    cgState.brightness = 0;
    cgState.contrast = 0;
    _nextLineId = 3;
    cgState.textLines = createDefaultTextLines('ra2');
    cgState.textBgDarkness = 38;
    cgState.textShadow = true;
    cgState.glass = 'another_glass';
    cgState.bevel = 'ra2_edges';
    cgState.cornerMask = 'shp_blue';
    cgState.veteran = 'none';
    cgState.fakeBanner = 'none';
    cgState.darkCorners = true;
    cgState.badgeUpgrade = false;
    cgState.badgeAmphibious = false;
    cgState.badgeJumpjet = false;
    cgState.selectedElementId = null;
    cgState.elementOffsets = createDefaultElementOffsets();
    cgState.elementOrder = createDefaultElementOrder(cgState.textLines);
    cgState.hiddenElements = {};
    cgState.layerOverrides = {};

    try {
        localStorage.removeItem(CG_STORAGE_KEY_STATE);
        localStorage.removeItem(CG_STORAGE_KEY_IMAGE);
    } catch (e) {}

    syncUiFromState();
    updateCameoPreview();
}

export async function loadImageFromFile(file) {
    if (!file) return;
    try {
        invalidateScaleCache();
        if (file.name && file.name.toLowerCase().endsWith('.pcx')) {
            const ab = await file.arrayBuffer();
            const pcx = new PcxLoader(ab).decode();
            if (pcx && pcx.indices && pcx.palette) {
                const imgData = new ImageData(pcx.width, pcx.height);
                const dst = imgData.data;
                const c0 = pcx.palette[0] || { r: 0, g: 0, b: 0 };
                const isChroma0 = (c0.r === 0 && c0.g === 0 && c0.b === 255) || (c0.r >= 250 && c0.g === 0 && c0.b >= 250);
                for (let i = 0; i < pcx.indices.length; i++) {
                    const idx = pcx.indices[i];
                    if (idx === 0 && isChroma0) {
                        dst[i * 4 + 3] = 0;
                    } else {
                        const col = pcx.palette[idx] || { r: 0, g: 0, b: 0 };
                        dst[i * 4] = col.r;
                        dst[i * 4 + 1] = col.g;
                        dst[i * 4 + 2] = col.b;
                        dst[i * 4 + 3] = 255;
                    }
                }
                cgState.srcImageData = imgData;
                cgState.srcLabel = `${file.name} (${pcx.width}×${pcx.height})`;
                cgState.panX = 0;
                cgState.panY = 0;
                cgState.zoomPct = 100;
                cgState.selectedElementId = 'unit';
                if (cgState.hiddenElements) delete cgState.hiddenElements.unit;
                saveCameoImageToStorage();
                syncUiFromState();
                await updateCameoPreview();
                return;
            }
        }
        const blobObj = (file instanceof Blob) ? file : new Blob([await file.arrayBuffer()]);
        const url = URL.createObjectURL(blobObj);
        const img = new Image();
        await new Promise((resolve, reject) => {
            img.onload = resolve;
            img.onerror = reject;
            img.src = url;
        });
        URL.revokeObjectURL(url);

        const c = document.createElement('canvas');
        c.width = img.naturalWidth || img.width;
        c.height = img.naturalHeight || img.height;
        const ctx = c.getContext('2d');
        ctx.drawImage(img, 0, 0);

        cgState.srcImageData = ctx.getImageData(0, 0, c.width, c.height);
        cgState.srcLabel = `${file.name} (${c.width}×${c.height})`;
        cgState.panX = 0;
        cgState.panY = 0;
        cgState.zoomPct = 100;
        cgState.selectedElementId = 'unit';
        if (cgState.hiddenElements) delete cgState.hiddenElements.unit;

        saveCameoImageToStorage();
        syncUiFromState();
        await updateCameoPreview();
    } catch (err) {
        console.error('Failed to load cameo source image:', err);
    }
}

function findLayerByIdRecursive(layers, id) {
    if (!layers || !id) return null;
    for (const l of layers) {
        if (l.id === id) return l;
        const children = l.layers || l.children;
        if (children) {
            const found = findLayerByIdRecursive(children, id);
            if (found) return found;
        }
    }
    return null;
}

export function useActiveEditorFrame() {
    if (!state || !state.frames || state.frames.length === 0) return;
    const frameIdx = state.currentFrameIdx || 0;
    const frame = state.frames[frameIdx];
    if (!frame || !frame.layers || frame.layers.length === 0) return;

    invalidateScaleCache();
    const w = state.canvasW || frame.width || 60;
    const h = state.canvasH || frame.height || 48;
    const imgData = new ImageData(w, h);
    let labelSuffix = '';

    const activeLayer = findLayerByIdRecursive(frame.layers, state.activeLayerId);

    if (state.isAlphaImageMode && frame.layers[0] && frame.layers[0].rgbaData) {
        imgData.data.set(frame.layers[0].rgbaData);
    } else if (activeLayer && activeLayer.type !== 'group' && activeLayer.data) {
        const pal = (state.palette && state.palette.some(col => col !== null)) ? state.palette : getRa2CameoPalette();
        const lw = activeLayer.width || w;
        const lh = activeLayer.height || h;
        const lx = activeLayer.x || 0;
        const ly = activeLayer.y || 0;
        for (let sy = 0; sy < lh; sy++) {
            const dy = ly + sy;
            if (dy < 0 || dy >= h) continue;
            for (let sx = 0; sx < lw; sx++) {
                const dx = lx + sx;
                if (dx < 0 || dx >= w) continue;
                const idx = activeLayer.data[sy * lw + sx];
                const di = (dy * w + dx) * 4;
                if (idx === TRANSPARENT_COLOR || idx === 0) {
                    imgData.data[di + 3] = 0;
                } else {
                    const col = pal[idx] || { r: 0, g: 0, b: 0 };
                    imgData.data[di] = col.r;
                    imgData.data[di + 1] = col.g;
                    imgData.data[di + 2] = col.b;
                    imgData.data[di + 3] = 255;
                }
            }
        }
        labelSuffix = activeLayer.name ? ` - ${activeLayer.name}` : '';
    } else {
        const flat = compositeFrame(frame, {
            transparentIdx: TRANSPARENT_COLOR,
            floatingSelection: state.floatingSelection,
            showIndex0: false,
            backgroundIdx: 0
        });
        const pal = (state.palette && state.palette.some(col => col !== null)) ? state.palette : getRa2CameoPalette();
        for (let i = 0; i < flat.length; i++) {
            const idx = flat[i];
            if (idx === TRANSPARENT_COLOR || idx === 0) {
                imgData.data[i * 4 + 3] = 0;
            } else {
                const col = pal[idx] || { r: 0, g: 0, b: 0 };
                imgData.data[i * 4] = col.r;
                imgData.data[i * 4 + 1] = col.g;
                imgData.data[i * 4 + 2] = col.b;
                imgData.data[i * 4 + 3] = 255;
            }
        }
    }

    cgState.srcImageData = imgData;
    cgState.srcLabel = `Frame #${frameIdx + 1}${labelSuffix} (${w}×${h})`;
    cgState.panX = 0;
    cgState.panY = 0;
    cgState.zoomPct = 100;
    cgState.selectedElementId = 'unit';
    if (cgState.hiddenElements) delete cgState.hiddenElements.unit;

    saveCameoImageToStorage();
    syncUiFromState();
    updateCameoPreview();
}

export function clearLoadedImage() {
    invalidateScaleCache();
    cgState.srcImageData = null;
    cgState.srcLabel = '';
    cgState.panX = 0;
    cgState.panY = 0;
    cgState.zoomPct = 100;
    cgState.brightness = 0;
    cgState.contrast = 0;
    if (cgState.selectedElementId === 'unit') {
        cgState.selectedElementId = null;
    }
    saveCameoImageToStorage();
    syncUiFromState();
    updateCameoPreview();
}


// ============================================================================
// EXPORT ACTIONS (.SHP, .PCX, .PNG, CLIPBOARD, NEW TAB, INSERT FRAME)
// ============================================================================
function cgDownloadBlob(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

function getSuggestedBaseName() {
    for (let i = cgState.textLines.length - 1; i >= 0; i--) {
        const txt = (cgState.textLines[i].text || '').trim().toLowerCase().replace(/[^a-z0-9_-]+/g, '');
        if (txt) return `${txt}icon`;
    }
    return 'cameoicon';
}

function quantizeRgbaAgainstPalette(imgData, W, H, pal, cornerMask, isChromaBlue) {
    const src = imgData.data;
    const isPcxMagenta = (cornerMask === 'pcx_magenta');
    const indices = new Uint8Array(W * H);

    for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
            const p = y * W + x;
            const di = p * 4;
            const r = src[di], g = src[di + 1], b = src[di + 2];
            if (src[di + 3] === 0) {
                indices[p] = 0;
            } else if (isPcxMagenta) {
                if (r === 253 && g === 0 && b === 253) {
                    indices[p] = 0;
                } else {
                    indices[p] = cgQuantizeInfurium(src, W, H, x, y, pal);
                }
            } else if ((isChromaBlue && isChromaBlue[p] === 1) || (r === 0 && g === 0 && b === 255)) {
                indices[p] = 0;
            } else {
                indices[p] = cgQuantizeInfurium(src, W, H, x, y, pal);
            }
        }
    }

    if (cornerMask === 'pcx_magenta' || cornerMask === 'shp_blue' || cornerMask === 'alpha0') {
        for (const [cx, cy] of getCornerCoords(W, H)) {
            indices[cy * W + cx] = 0;
        }
    } else if (cornerMask === 'black') {
        const blackIdx = quantizeLinearEuclidean(0, 0, 0, pal, 1);
        for (const [cx, cy] of getCornerCoords(W, H)) {
            indices[cy * W + cx] = blackIdx;
        }
    }
    return indices;
}

function buildAdaptivePaletteAndIndices(imgData, W, H, cornerMask, isChromaBlue, extraRgbBuffers = []) {
    const pal = new Array(256);
    const isPcxMagenta = (cornerMask === 'pcx_magenta');
    pal[0] = isPcxMagenta ? { r: 253, g: 0, b: 253 } : { r: 0, g: 0, b: 255 };

    const src = imgData.data;
    const freq = new Map();
    const addBufColors = (buf, weight, checkChroma) => {
        if (!buf) return;
        for (let p = 0; p < W * H; p++) {
            const di = p * 4;
            if (buf[di + 3] === 0) continue;
            const r = buf[di], g = buf[di + 1], b = buf[di + 2];
            if (isPcxMagenta) {
                if (r === 253 && g === 0 && b === 253) continue;
            } else {
                if (checkChroma && isChromaBlue && isChromaBlue[p] === 1) continue;
                if (r === 0 && g === 0 && b === 255) continue;
            }
            const key = (r << 16) | (g << 8) | b;
            freq.set(key, (freq.get(key) || 0) + weight);
        }
    };

    addBufColors(src, 4, true);
    if (Array.isArray(extraRgbBuffers)) {
        for (const eb of extraRgbBuffers) {
            addBufColors(eb, 1, false);
        }
    }

    let idx = 1;
    if (isPcxMagenta) {
        // Reserve pal[1] for pure blue RGB(0, 0, 255) so the Background layer remains blue while Index 0 is PCX Magenta
        pal[idx++] = { r: 0, g: 0, b: 255 };
        freq.delete((0 << 16) | (0 << 8) | 255);
    }
    // Always reserve pure black so text shadows and dark borders have an exact black entry
    pal[idx++] = { r: 0, g: 0, b: 0 };
    freq.delete(0);

    const sorted = Array.from(freq.entries()).sort((a, b) => b[1] - a[1]);
    const maxColors = 256 - idx;

    if (sorted.length <= maxColors) {
        for (let i = 0; i < sorted.length; i++) {
            const key = sorted[i][0];
            pal[idx++] = {
                r: (key >> 16) & 255,
                g: (key >> 8) & 255,
                b: key & 255
            };
        }
    } else {
        // Keep the top K highest-frequency exact colors, then select the remaining slots via
        // weighted Farthest-Point Sampling so all color regions (and un-glassed layers) are covered
        const nCand = sorted.length;
        const cR = new Int32Array(nCand);
        const cG = new Int32Array(nCand);
        const cB = new Int32Array(nCand);
        const cW = new Float32Array(nCand);
        const minDistSq = new Int32Array(nCand);
        const chosen = new Uint8Array(nCand);

        for (let i = 0; i < nCand; i++) {
            const key = sorted[i][0];
            const r = (key >> 16) & 255;
            const g = (key >> 8) & 255;
            const b = key & 255;
            cR[i] = r;
            cG[i] = g;
            cB[i] = b;
            cW[i] = 1 + Math.log2(Math.max(1, sorted[i][1]));
            // Distance to already reserved palette entries (e.g. black / blue)
            let bestD = 0x7fffffff;
            for (let pi = 1; pi < idx; pi++) {
                const dr = r - pal[pi].r;
                const dg = g - pal[pi].g;
                const db = b - pal[pi].b;
                const d = dr * dr + dg * dg + db * db;
                if (d < bestD) bestD = d;
            }
            minDistSq[i] = bestD;
        }

        const selectCandidate = (ci) => {
            chosen[ci] = 1;
            minDistSq[ci] = 0;
            const nr = cR[ci], ng = cG[ci], nb = cB[ci];
            pal[idx++] = { r: nr, g: ng, b: nb };
            for (let j = 0; j < nCand; j++) {
                if (chosen[j]) continue;
                const dr = cR[j] - nr;
                const dg = cG[j] - ng;
                const db = cB[j] - nb;
                const d = dr * dr + dg * dg + db * db;
                if (d < minDistSq[j]) minDistSq[j] = d;
            }
        };

        const directTop = Math.min(36, Math.floor(maxColors * 0.15));
        for (let i = 0; i < directTop && idx < 256; i++) {
            selectCandidate(i);
        }

        while (idx < 256) {
            let bestJ = -1;
            let bestScore = -1;
            for (let j = 0; j < nCand; j++) {
                if (chosen[j]) continue;
                const score = minDistSq[j] * cW[j];
                if (score > bestScore) {
                    bestScore = score;
                    bestJ = j;
                }
            }
            if (bestJ < 0 || bestScore <= 0) break;
            selectCandidate(bestJ);
        }
    }

    while (idx < 256) {
        pal[idx++] = { r: 0, g: 0, b: 0 };
    }

    const indices = quantizeRgbaAgainstPalette(imgData, W, H, pal, cornerMask, isChromaBlue);
    return { pal, indices };
}

function enrichPaletteUnusedSlots(usePal, frames, imgData, W, H, cornerMask, isChromaBlue) {
    if (!usePal || usePal.length < 256 || !Array.isArray(frames) || frames.length === 0) return false;
    const used = new Uint8Array(256);
    used[0] = 1;
    if (cornerMask === 'pcx_magenta') used[1] = 1;

    const scanNodes = (nodes) => {
        if (!Array.isArray(nodes)) return;
        for (const n of nodes) {
            if (n.type === 'group' && (n.layers || n.children)) {
                scanNodes(n.layers || n.children);
            } else if (n.data) {
                const d = n.data;
                for (let i = 0; i < d.length; i++) {
                    const v = d[i];
                    if (v >= 0 && v < 256) used[v] = 1;
                }
            }
        }
    };
    for (const f of frames) {
        if (f && f.layers) scanNodes(f.layers);
    }

    const freeSlots = [];
    for (let i = 1; i < 256; i++) {
        if (!used[i]) freeSlots.push(i);
    }
    if (freeSlots.length === 0) return false;

    const src = imgData.data;
    const isPcxMagenta = (cornerMask === 'pcx_magenta');
    const freq = new Map();
    for (let p = 0; p < W * H; p++) {
        const di = p * 4;
        if (src[di + 3] === 0) continue;
        const r = src[di], g = src[di + 1], b = src[di + 2];
        if (isPcxMagenta) {
            if (r === 253 && g === 0 && b === 253) continue;
        } else {
            if (isChromaBlue && isChromaBlue[p] === 1) continue;
            if (r === 0 && g === 0 && b === 255) continue;
        }
        const key = (r << 16) | (g << 8) | b;
        freq.set(key, (freq.get(key) || 0) + 1);
    }

    const sorted = Array.from(freq.entries()).sort((a, b) => b[1] - a[1]);
    if (sorted.length === 0) return false;

    const nCand = sorted.length;
    const cR = new Int32Array(nCand);
    const cG = new Int32Array(nCand);
    const cB = new Int32Array(nCand);
    const cW = new Float32Array(nCand);
    const minDistSq = new Int32Array(nCand);
    const chosen = new Uint8Array(nCand);

    for (let i = 0; i < nCand; i++) {
        const key = sorted[i][0];
        const r = (key >> 16) & 255;
        const g = (key >> 8) & 255;
        const b = key & 255;
        cR[i] = r;
        cG[i] = g;
        cB[i] = b;
        cW[i] = 1 + Math.log2(Math.max(1, sorted[i][1]));
        let bestD = 0x7fffffff;
        for (let pi = 1; pi < 256; pi++) {
            if (!used[pi] || !usePal[pi]) continue;
            const dr = r - usePal[pi].r;
            const dg = g - usePal[pi].g;
            const db = b - usePal[pi].b;
            const d = dr * dr + dg * dg + db * db;
            if (d < bestD) bestD = d;
        }
        minDistSq[i] = bestD;
    }

    let changed = false;
    for (const slot of freeSlots) {
        let bestJ = -1;
        let bestScore = -1;
        for (let j = 0; j < nCand; j++) {
            if (chosen[j]) continue;
            const score = minDistSq[j] * cW[j];
            if (score > bestScore) {
                bestScore = score;
                bestJ = j;
            }
        }
        if (bestJ < 0 || bestScore <= 0) break;
        chosen[bestJ] = 1;
        minDistSq[bestJ] = 0;
        const nr = cR[bestJ], ng = cG[bestJ], nb = cB[bestJ];
        usePal[slot] = { r: nr, g: ng, b: nb };
        used[slot] = 1;
        changed = true;
        for (let j = 0; j < nCand; j++) {
            if (chosen[j]) continue;
            const dr = cR[j] - nr;
            const dg = cG[j] - ng;
            const db = cB[j] - nb;
            const d = dr * dr + dg * dg + db * db;
            if (d < minDistSq[j]) minDistSq[j] = d;
        }
    }
    return changed;
}

export async function exportAsShpFile() {
    const { imgData, indexedFrame, W, H, isChromaBlue, preGlassRgb } = await compositeCameoCanvas();
    const indices = (cgState.paletteMode === 'full')
        ? buildAdaptivePaletteAndIndices(imgData, W, H, cgState.cornerMask, isChromaBlue, [preGlassRgb]).indices
        : new Uint8Array(indexedFrame);

    const frameObj = {
        x: 0,
        y: 0,
        width: W,
        height: H,
        flags: 3,
        frameColor: { r: 0, g: 0, b: 0 },
        originalIndices: indices
    };
    const shpBuf = ShpFormat80.encode([frameObj], W, H, 3);
    const blob = new Blob([shpBuf], { type: 'application/octet-stream' });
    cgDownloadBlob(blob, `${getSuggestedBaseName()}.shp`);
}

export async function exportAsPcxFile() {
    const { imgData, indexedFrame, pal, W, H, isChromaBlue, preGlassRgb } = await compositeCameoCanvas();
    let outPal;
    let indices;
    if (cgState.paletteMode === 'full') {
        const adaptive = buildAdaptivePaletteAndIndices(imgData, W, H, cgState.cornerMask, isChromaBlue, [preGlassRgb]);
        outPal = adaptive.pal;
        indices = adaptive.indices;
    } else {
        outPal = pal.map(c => c ? { ...c } : { r: 0, g: 0, b: 0 });
        indices = new Uint8Array(indexedFrame);
        if (cgState.cornerMask === 'pcx_magenta') {
            outPal[0] = { r: 253, g: 0, b: 253 };
            const blueIdx = quantizeLinearEuclidean(0, 0, 255, outPal, 1);
            for (let p = 0; p < W * H; p++) {
                if (indices[p] === 0) indices[p] = blueIdx;
            }
            for (const [cx, cy] of getCornerCoords(W, H)) {
                indices[cy * W + cx] = 0;
            }
        } else if (cgState.cornerMask === 'shp_blue') {
            outPal[0] = { r: 0, g: 0, b: 255 };
            for (const [cx, cy] of getCornerCoords(W, H)) {
                indices[cy * W + cx] = 0;
            }
        }
    }

    const pcxBytes = PcxLoader.encode(W, H, indices, outPal);
    const blob = new Blob([pcxBytes], { type: 'application/octet-stream' });
    cgDownloadBlob(blob, `${getSuggestedBaseName()}.pcx`);
}

export async function exportAsPngFile() {
    const { imgData, W, H } = await compositeCameoCanvas();
    const c = document.createElement('canvas');
    c.width = W;
    c.height = H;
    c.getContext('2d').putImageData(imgData, 0, 0);
    c.toBlob(blob => {
        if (blob) cgDownloadBlob(blob, `${getSuggestedBaseName()}.png`);
    }, 'image/png');
}

export async function copyCameoToClipboard() {
    const { imgData, W, H } = await compositeCameoCanvas();
    const c = document.createElement('canvas');
    c.width = W;
    c.height = H;
    c.getContext('2d').putImageData(imgData, 0, 0);

    try {
        const blob = await new Promise(resolve => c.toBlob(resolve, 'image/png'));
        if (!blob) return;
        if (isNativeApp()) {
            const ab = await blob.arrayBuffer();
            await nativeWriteClipboardImage(new Uint8Array(ab));
        } else if (navigator.clipboard && window.ClipboardItem) {
            await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
        }
        if (typeof showPasteNotification === 'function') {
            showPasteNotification(t('cg_msg_copied_clipboard') || 'Cameo copied to clipboard!', 'success', 2200);
        }
    } catch (err) {
        console.warn('[CameoGenerator] Clipboard write error:', err);
    }
}

